def find_rel(g):
    h,w=len(g),len(g[0])
    res=[]
    for a in range(2*h):
        if all(g[i][j]==g[(a-i)%h][j] for i in range(h) for j in range(w)): res.append(('v',a))
    for a in range(2*w):
        if all(g[i][j]==g[i][(a-j)%w] for i in range(h) for j in range(w)): res.append(('h',a))
    for a in range(h+w):
        if all(g[i][j]==g[(a-i)%h][(a-j)%w] for i in range(h) for j in range(w)): res.append(('r',a))
    for a in range(h+w):
        if all(g[i][j]==g[(a-j)%h][(a-i)%w] for i in range(h) for j in range(w)): res.append(('t',a))
    return res
